import sys
from itertools import product

MOD = 10 ** 9 + 7

def mul(X, Y):
    return (
        (X[0] * Y[0] + X[1] * Y[2]) % MOD, (X[0] * Y[1] + X[1] * Y[3]) % MOD,
        (X[2] * Y[0] + X[3] * Y[2]) % MOD, (X[2] * Y[1] + X[3] * Y[3]) % MOD,
    )

def cycle_colourings(g, k):
    # a_1 = 0, a_2 = k(k-1), a_g = (k-2)a_{g-1} + (k-1)a_{g-2}
    if g == 1:
        return 0
    a2 = k % MOD * ((k - 1) % MOD) % MOD
    if g == 2:
        return a2
    base = ((k - 2) % MOD, (k - 1) % MOD, 1, 0)
    acc = (1, 0, 0, 1)
    e = g - 2
    while e:
        if e & 1:
            acc = mul(acc, base)
        base = mul(base, base)
        e >>= 1
    return acc[0] * a2 % MOD

